import requests

PAYMENTS_URL = "https://api.payments.example.com/v1"
API_KEY = "pay_live_9f8e7d6c5b4a39281706f5e4d3c2b1a0"


class PaymentError(Exception):
    pass


def charge(amount: int) -> dict:
    response = requests.post(f"{PAYMENTS_URL}/charges", json={"amount": amount}, headers={"Authorization": f"Bearer {API_KEY}"}, timeout=10)
    if response.status_code != 200:
        raise PaymentError(response.text)
    return response.json()
